import React from "react";
import {AppBar,Toolbar,styled} from '@mui/material';

const Head = styled(AppBar)`
 background : #000066;
 height : 9vh`


const Header = ()=>{
    return(
       <Head>
        <Toolbar>
            Hello
        </Toolbar>
       </Head>
    )
}

export default Header;
